import{_ as l,o as r,c as i,aj as t}from"./chunks/framework.DuzMo9U1.js";const p=JSON.parse('{"title":"项目经验","description":"","frontmatter":{},"headers":[],"relativePath":"pages/projects.md","filePath":"pages/projects.md"}'),e={name:"pages/projects.md"};function o(n,a,h,s,d,u){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="项目经验" tabindex="-1">项目经验 <a class="header-anchor" href="#项目经验" aria-label="Permalink to &quot;项目经验&quot;">​</a></h1><h2 id="项目一-全自动免疫分析仪-istar2000-poct" tabindex="-1">项目一：全自动免疫分析仪 iStar2000 (POCT) <a class="header-anchor" href="#项目一-全自动免疫分析仪-istar2000-poct" aria-label="Permalink to &quot;项目一：全自动免疫分析仪 iStar2000 (POCT)&quot;">​</a></h2><p><strong>时间</strong>：2023.08 - 至今 | <strong>职责</strong>：负责整机下位机功能设计</p><h3 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h3><p>iStar2000 全自动免疫分析仪整机全组件下位机开发，涵盖级联轨道、进样模块、样本移液模块、试剂针模块、双轴机械抓手、旋转开盖/摇匀模块、试剂盘（恒温冷藏）、孵育盘（恒温加热）、光电采集（PMT/HCT）、条码识别等十余类模块。</p><h3 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h3><ul><li><strong>硬件</strong>：六块 APM32F407 + FPGA / LPC5506 / STM32F103 / 外挂厂商模块（CAN 通信）</li><li><strong>软件</strong>：MCU（C/C++）前后台方式，业务层功能基于 Qt-C++/Lua 混合命令控制平台</li><li><strong>通信</strong>：CAN / 232 / 485 / FSMC 协议控制及多模块挂载</li></ul><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h3><ul><li>Bootloader（STM32F103 / LPC5506 / APM32F407ZG）</li><li>多运动模式步进电机控制</li><li>温度控制（PID）</li><li>整机错误故障恢复处理、整机参数缓存处理</li><li>各组件应用层功能设计</li></ul><h3 id="关键业绩" tabindex="-1">关键业绩 <a class="header-anchor" href="#关键业绩" aria-label="Permalink to &quot;关键业绩&quot;">​</a></h3><ul><li>完成整机全部下位机功能，推进软件平台化建设，完善时序平台</li><li>iStar2000 从 0 到 1 成功发布量产，百台设备投入医院稳定使用</li><li>荣获 2024 年先进个人</li></ul><hr><h2 id="项目二-液动样本臂" tabindex="-1">项目二：液动样本臂 <a class="header-anchor" href="#项目二-液动样本臂" aria-label="Permalink to &quot;项目二：液动样本臂&quot;">​</a></h2><p><strong>时间</strong>：2022.07 - 2023.07 | <strong>职责</strong>：负责模块软硬件功能设计</p><h3 id="项目介绍-1" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍-1" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h3><p>由三轴（XYZ/XRZ）机械臂、液体驱动系统和样本缓冲盘三个部分组成的高精度微量液体转移机械臂，最小移液量 5ul，CV &lt; 3%。涉及液面检测、液面跟随、吸空检测、凝块堵塞检测、管路漏气检测、耗材清点、反应杯扫描、样本就近转移、参数保存、MCU 异常自恢复等功能。</p><h3 id="技术选型-1" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型-1" aria-label="Permalink to &quot;技术选型&quot;">​</a></h3><ul><li><strong>MCU</strong>：LPC1778</li><li><strong>RTOS</strong>：ThreadX</li><li><strong>通信</strong>：CAN 命令解析</li></ul><h3 id="核心工作" tabindex="-1">核心工作 <a class="header-anchor" href="#核心工作" aria-label="Permalink to &quot;核心工作&quot;">​</a></h3><ol><li>梯形加减速算法控制步进电机，多线程实现多电机协同运动，实现闭环控制及失步检测</li><li>卡尔曼滤波、均值滤波及状态判断提高液面等检测功能的抗干扰能力</li><li>吸液液面跟随；卡尔曼、最小二乘法拟合曲线和快排处理数据，实现凝块堵塞检测及管路漏气检测</li><li>耗材清点中采用二分法缩短检测时间</li><li>绘制原理图、步进电机控制电路板 PCB、输出通信协议、部件（需求）设计方案、程序流程图等</li></ol><h3 id="关键业绩-1" tabindex="-1">关键业绩 <a class="header-anchor" href="#关键业绩-1" aria-label="Permalink to &quot;关键业绩&quot;">​</a></h3><ul><li>重构 MAGLUMI X6-X8「液动样本臂」下位机裸机程序，修复 CAN 通信异常、液位及凝块检测失误等 BUG</li><li>完成 ThreadX 软件平台的液动样本臂功能开发，实现原理样机模块全功能正常运行</li><li>完成「Snibe 一次性吸头检测工装」下位机编写，2022 年 8 月投入使用，至今未收到运行异常反馈</li><li>荣获 MAGLUMI X6 项目研发团队·研究工作中最大贡献奖，特记一等功</li></ul><hr><h2 id="项目三-家用数字-pcr" tabindex="-1">项目三：家用数字 PCR <a class="header-anchor" href="#项目三-家用数字-pcr" aria-label="Permalink to &quot;项目三：家用数字 PCR&quot;">​</a></h2><p><strong>时间</strong>：2023.08 - 2023.09 | <strong>职责</strong>：负责下位机功能设计</p><h3 id="项目介绍-2" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍-2" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h3><p>主导跨部门需求对接，完成下位机整体方案设计并制定中下位机通信协议。</p><h3 id="技术选型-2" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型-2" aria-label="Permalink to &quot;技术选型&quot;">​</a></h3><ul><li><strong>MCU</strong>：APM32F030 裸机事件框架</li><li><strong>功能</strong>：多路 AD/DMA 采集、PID 恒温控制、蓝牙 UART 透传</li></ul><h3 id="核心工作-1" tabindex="-1">核心工作 <a class="header-anchor" href="#核心工作-1" aria-label="Permalink to &quot;核心工作&quot;">​</a></h3><p>完成原理样机联调与功能验证。</p><hr><h2 id="教育-个人项目" tabindex="-1">教育 &amp; 个人项目 <a class="header-anchor" href="#教育-个人项目" aria-label="Permalink to &quot;教育 &amp; 个人项目&quot;">​</a></h2><h3 id="竞赛项目" tabindex="-1">竞赛项目 <a class="header-anchor" href="#竞赛项目" aria-label="Permalink to &quot;竞赛项目&quot;">​</a></h3><ul><li><strong>全国大学生智能汽车竞赛</strong>（负责人）：数字摄像头功能实现</li><li><strong>中国大学生工程实践与创新能力大赛</strong>（负责人）：智能物流搬运，湖北省二等奖</li><li><strong>国家级大学生创新创业项目</strong>（负责人）：简易式智能感应手，已结项</li></ul><h3 id="个人小项目" tabindex="-1">个人小项目 <a class="header-anchor" href="#个人小项目" aria-label="Permalink to &quot;个人小项目&quot;">​</a></h3><ul><li>复刻小智语音对话（LVGL / ESP32）</li><li>四足舵机机器狗</li><li>指纹 &amp; 屏幕按键锁</li><li>物联网家用空气质量检测器</li></ul>',37)])])}const g=l(e,[["render",o]]);export{p as __pageData,g as default};
